function toggleSym(zbior, wartosc) {
  if (zbior.has(wartosc)) {
    zbior.delete(wartosc);
  } else {
    zbior.add(wartosc);
  }
  return zbior.has(wartosc);
}

const klasy = new Set(["card"]);
console.log(toggleSym(klasy, "active"));
console.log(toggleSym(klasy, "active"));

