function toggleZWarunkiem(zbior, wartosc, warunek) {
  if (warunek) {
    zbior.add(wartosc);
  } else {
    zbior.delete(wartosc);
  }
  return zbior.has(wartosc);
}

const klasy = new Set();
console.log(toggleZWarunkiem(klasy, "active", true));
console.log(toggleZWarunkiem(klasy, "active", false));

// classList dziala jak zestaw przelacznikow na panelu sterowania -
// kazda klasa to osobny przelacznik, ktory mozna:
// - wlaczyc (add) - dodac klase
// - wylaczyc (remove) - usunac klase
// - przelaczyc (toggle) - odwrocic aktualny stan
// - sprawdzic aktualny stan (contains) - bez wplywu na pozostale
// przelaczniki (inne klasy) na tym samym panelu (elemencie).

const produkt = document.getElementById("product-1");
produkt.className = "card active";
console.log(produkt.classList.contains("card"), produkt.classList.contains("active"));

function policzKlasy(elementId) {
  return document.getElementById(elementId).classList.length;
}

const produkt = document.getElementById("product-1");
produkt.classList.add("a", "b", "c");
console.log(policzKlasy("product-1"));

const produkt = document.getElementById("product-3");
produkt.classList.remove("card");
produkt.classList.add("card");
console.log(produkt.classList.contains("card"));

